// Date window + your true store numbers. Meta, TikTok and Google Ads are pulled
// live below. Add any OTHER platforms manually in EXTRA_PLATFORMS.
const end = new Date();
const start = new Date(Date.now() - 30 * 864e5);
const fmt = (dt) => dt.toISOString().slice(0, 10);
return [{ json: {
  DATE_PRESET: 'last_30d',        // Meta window
  START_DATE: fmt(start),         // TikTok + Google window
  END_DATE: fmt(end),
  STORE_REVENUE: 120000,          // replace with a Shopify or Stripe node
  NEW_CUSTOMERS: 320,             // replace with your real new-customer count
  EXTRA_PLATFORMS: [],            // e.g. { platform: 'Snapchat', spend: 0, reported_revenue: 0 }
} }];

// Compute the efficiency metrics every ecommerce operator actually tracks.
const { platforms, store_revenue, new_customers } = $json;
const total_spend = +platforms.reduce((n, p) => n + p.spend, 0).toFixed(2);
const total_reported = +platforms.reduce((n, p) => n + p.reported_revenue, 0).toFixed(2);

const blended_roas = total_spend ? +(store_revenue / total_spend).toFixed(2) : null;      // real revenue / all ad spend
const mer = blended_roas;                                                                  // marketing efficiency ratio
const blended_cac = new_customers ? +(total_spend / new_customers).toFixed(2) : null;      // cost to acquire a customer
const over_claim = +(total_reported - store_revenue).toFixed(2);                           // platforms claim more than the store made
const over_claim_pct = store_revenue ? Math.round((over_claim / store_revenue) * 100) : null;

const byPlatform = platforms.map((p) => ({ ...p, reported_roas: p.spend ? +(p.reported_revenue / p.spend).toFixed(2) : null }));
return [{ json: { total_spend, total_reported, store_revenue, blended_roas, mer, blended_cac, new_customers, over_claim, over_claim_pct, byPlatform } }];

// Ask Claude for a short marketing-efficiency brief a founder can act on.
const m = $json;
const system = 'You are a growth-marketing analyst. Given blended ROAS, MER, blended CAC, and the gap between platform-reported and actual store revenue, write a 2-3 sentence executive read: is marketing efficient, how much are platforms over-claiming, and the single most important action. Terse and specific. Return ONLY JSON.';
const user = JSON.stringify(m) + '\n\nReturn JSON exactly: {"verdict":"one sentence","overclaim_note":"one sentence","action":"one sentence"}';
const body = { model: 'claude-haiku-4-5', max_tokens: 700, system, messages: [{ role: 'user', content: user }] };
return [{ json: { body, _ctx: m } }];

// Pull spend + reported revenue from all three live platforms into one table.
const cfg = $('Set config: store revenue, new customers, extra platforms').first().json;
// Meta
const mRow = (($('Fetch Meta spend & revenue (Meta)').first().json.data)||[{}])[0] || {};
const REV = ['onsite_web_app_purchase','omni_purchase','offsite_conversion.fb_pixel_purchase','purchase'];
const mSpend = Number(mRow.spend)||0;
let mRev=0; for (const t of REV){ const av=(mRow.action_values||[]).find(a=>a.action_type===t); if(av){ mRev=Number(av.value)||0; break; } }
// TikTok
const tt = ((($('Fetch TikTok spend & revenue').first().json.data)||{}).list||[{}])[0] || {};
const ttm = tt.metrics||{};
const ttSpend = Number(ttm.spend)||0;
const ttRev = Number(ttm.total_complete_payment_rate)||0;
// Google Ads (cost_micros -> currency)
const g = ((($('Fetch Google Ads spend & revenue').first().json.results)||[{}])[0]||{}).metrics||{};
const gSpend = (Number(g.costMicros)||0)/1e6;
const gRev = Number(g.conversionsValue)||0;
const platforms = [
  { platform:'Meta',   spend:+mSpend.toFixed(2),  reported_revenue:+mRev.toFixed(2) },
  { platform:'TikTok', spend:+ttSpend.toFixed(2), reported_revenue:+ttRev.toFixed(2) },
  { platform:'Google', spend:+gSpend.toFixed(2),  reported_revenue:+gRev.toFixed(2) },
  ...(cfg.EXTRA_PLATFORMS||[]),
];
return [{ json: { platforms, store_revenue: cfg.STORE_REVENUE, new_customers: cfg.NEW_CUSTOMERS } }];

// Print the blended ROAS / MER scorecard.
const m = $node['Reconcile blended ROAS, MER & platform over-claim gap'].json;
const raw = ($json.content && $json.content[0] && $json.content[0].text) || '{}';
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
let ai = { verdict: '', overclaim_note: '', action: '' };
try { ai = JSON.parse(raw.slice(s, e + 1)); } catch (err) {}

const out = [];
out.push('');
out.push('==========================================================');
out.push('  BLENDED ROAS & MER RECONCILER  |  nocode.expert');
out.push('==========================================================');
out.push('Total ad spend:        $' + m.total_spend.toLocaleString());
out.push('Actual store revenue:  $' + m.store_revenue.toLocaleString());
out.push('Blended ROAS / MER:    ' + m.blended_roas + 'x');
out.push('Blended CAC:           ' + (m.blended_cac !== null ? '$' + m.blended_cac : 'n/a') + '  (' + (m.new_customers || 'n/a') + ' new customers)');
out.push('');
out.push('Platforms CLAIM:       $' + m.total_reported.toLocaleString() + '  ->  over-claim $' + m.over_claim.toLocaleString() + ' (' + m.over_claim_pct + '% of real revenue)');
out.push('');
out.push('Per platform (spend | reported rev | reported ROAS):');
for (const p of m.byPlatform) out.push('  ' + p.platform.padEnd(12) + '$' + String(p.spend).padStart(9) + ' | $' + String(p.reported_revenue).padStart(9) + ' | ' + p.reported_roas + 'x');
out.push('');
out.push('Verdict:   ' + (ai.verdict || ''));
out.push('Over-claim: ' + (ai.overclaim_note || ''));
out.push('Action:    ' + (ai.action || ''));
out.push('==========================================================');
return [{ json: { report: out.join('\n'), ...m } }];
